#pragma once
#include <memory>
#include <vector>
#include <string>
#include <mutex>
#include "Event.h"
#include "Formatter.h"
#include "Appender.h"
namespace ws {
namespace log {
class Logger {
public:
    using Ptr = std::shared_ptr<Logger>;

    Logger(const std::string& name, Level level, size_t capacity);

    void Log(Event::Ptr event);
    void AddAppender(Appender::Ptr appender);
    void RemoveAppender(Appender::Ptr appender);
    void ClearAppenders();

    Level GetLevel() const;
    void SetLevel(Level level);

    Formatter::Ptr GetDefaultFormatter() const;
    void SetDefaultFormatter(Formatter::Ptr formatter);

    std::string ToYamlString() const;

private:
    std::string name_;
    Level level_;
    size_t capacity_;
    std::vector<Appender::Ptr> appenders_;
    Formatter::Ptr formatter_;
    mutable std::mutex mutex_;
};
}
}

#pragma once
#include <memory>
#include <string>
namespace ws {
namespace log {
class Event {
public:
    using Ptr = std::shared_ptr<Event>;

    static Ptr Create(Level level, const std::string& file_name, int line_num, uint64_t thread_id, const std::string& msg);

    Level Level() const;
    const std::string& FileName() const;
    int LineNum() const;
    uint64_t ThreadId() const;
    const std::string& Time() const;

    std::ostringstream& Message();
    std::ostringstream& MessageStream();

private:
    Event(Level level, const std::string& file_name, int line_num, uint64_t thread_id);

    Level level_;
    std::string file_name_;
    int line_num_;
    uint64_t thread_id_;
    std::string time_;
    std::ostringstream msg_;
};
}
}

#pragma once
#include <memory>
#include <string>
namespace ws {
namespace log {
class Formatter {
public:
    using Ptr = std::shared_ptr<Formatter>;

    static Ptr Default();

    Formatter(const std::string& pattern);

    std::string Format(const Logger& logger, const Event& event) const;

private:
    std::string pattern_;
    std::vector<FieldFormatter::Ptr> fields_;
};
}
}

#pragma once
#include <memory>
#include "Logger.h"
#include "Event.h"
namespace ws {
namespace log {
class Appender {
public:
    using Ptr = std::shared_ptr<Appender>;

    virtual ~Appender() {}

    void SetFormatter(Formatter::Ptr formatter);

    virtual void Log(const Logger& logger, const Event& event) = 0;

    std::string ToYamlString() const;

protected:
    Formatter::Ptr formatter_;
};
}
}

#include "StdOutAppender.h"
#include <iostream>
namespace ws {
namespace log {
void StdOutAppender::Log(const Logger& logger, const Event& event) {
    if (formatter_) {
        std::cout << formatter_->Format(logger, event);
    }
}
}
}

#pragma once
#include "Appender.h"
namespace ws {
namespace log {
class StdOutAppender : public Appender {
public:
    using Ptr = std::shared_ptr<StdOutAppender>;

    void Log(const Logger& logger, const Event& event) override;
};
}
}

#include "FileAppender.h"
#include <fstream>
namespace ws {
namespace log {
FileAppender::FileAppender(const std::string& file_name)
    : file_name_(file_name), file_(file_name, std::ios::app) {}

void FileAppender::Log(const Logger& logger, const Event& event) {
    if (formatter_ && file_.is_open()) {
        file_ << formatter_->Format(logger, event);
    }
}
}
}
